import type { EventDoc, PuzzleResult, SaveDoc } from '../types';
import type { AdminPlayer } from './data';
import type { CatalogEntry } from './eventText';

/** Section 11 evaluation, computed in the client from saves and events [ADM-11]. */

export type AnyEvent = EventDoc & { id?: string };

/** Catalog entries as generated by content:compile (with day). */
export type DayCatalogEntry = CatalogEntry & { day: number };

/** [ADM-8] Only the current run of each player, oldest first. */
export function currentRunEvents(players: readonly AdminPlayer[], events: readonly AnyEvent[]): Map<string, AnyEvent[]> {
  const runOf = new Map(players.map((p) => [p.user.uid, p.user.runId]));
  const out = new Map<string, AnyEvent[]>(players.map((p) => [p.user.uid, []]));
  for (const e of events) {
    if (runOf.get(e.uid) !== e.runId) continue;
    out.get(e.uid)!.push(e);
  }
  for (const list of out.values()) list.sort((a, b) => a.at - b.at);
  return out;
}

/** The latest option each player took per choice point (cid → uid → option). */
export function latestChoices(byUid: Map<string, AnyEvent[]>): Map<string, Map<string, string>> {
  const out = new Map<string, Map<string, string>>();
  for (const [uid, events] of byUid) {
    for (const e of events) {
      if (e.type !== 'choice') continue;
      const cid = String(e.data.cid);
      if (!out.has(cid)) out.set(cid, new Map());
      out.get(cid)!.set(uid, String(e.data.option));
    }
  }
  return out;
}

export interface DecisionRow {
  id: string;
  day: number;
  question: string;
  options: Array<{ option: string; text: string; uids: string[] }>;
  total: number;
}

/** admin.decisions: per day, per choice point the options and who chose them. */
export function decisionStats(catalog: readonly DayCatalogEntry[], byUid: Map<string, AnyEvent[]>): Map<number, DecisionRow[]> {
  const chosen = latestChoices(byUid);
  const days = new Map<number, DecisionRow[]>();
  for (const entry of catalog) {
    const picks = chosen.get(entry.id) ?? new Map<string, string>();
    const options = entry.options.map((o) => ({
      option: o.option,
      text: o.text,
      uids: [...picks].filter(([, option]) => option === o.option).map(([uid]) => uid),
    }));
    const row: DecisionRow = { id: entry.id, day: entry.day, question: entry.question, options, total: picks.size };
    if (!days.has(entry.day)) days.set(entry.day, []);
    days.get(entry.day)!.push(row);
  }
  return days;
}

export interface PlayerSummary {
  hatSuggestion: string | null;
  house: string | null;
  overruled: boolean;
  route: string;
  accused: string;
  ending: string | null;
}

/** admin.decisions header line per player. */
export function playerSummary(save: SaveDoc | null): PlayerSummary {
  const p = save?.profile;
  return {
    hatSuggestion: p?.hatSuggestion ?? null,
    house: p?.house ?? null,
    overruled: p?.hatOverruled ?? false,
    route: String(save?.vars.route ?? ''),
    accused: String(save?.vars.accused ?? ''),
    ending: save?.ending ?? null,
  };
}

export interface PuzzleStat {
  id: string;
  /** Players who opened it (have a result entry). */
  started: number;
  solved: number;
  avgAttempts: number | null;
  avgDurationSec: number | null;
  /** Share of solvers who opened at least one hint (free pet hints count). */
  hintRate: number | null;
  /** Share of solvers who took Quill's help. */
  helpRate: number | null;
  /** Section 11.3: Ø too long (DECISIONS.md #55: 8 instead of 3 min) or help > 30 %. */
  flagged: boolean;
}

export const FLAG_DURATION_SEC = 8 * 60;
export const FLAG_HELP_RATE = 0.3;

const avg = (values: number[]): number | null => (values.length ? values.reduce((a, b) => a + b, 0) / values.length : null);

/** admin.puzzles, from the saves of the current runs (the authoritative results). */
export function puzzleStats(puzzleIds: readonly string[], players: readonly AdminPlayer[]): PuzzleStat[] {
  return puzzleIds.map((id) => {
    const results = players.map((p) => p.save?.puzzles[id]).filter((r): r is PuzzleResult => !!r);
    const solved = results.filter((r) => r.solved);
    const durations = solved.map((r) => r.durationSec).filter((d): d is number => typeof d === 'number');
    const stat: PuzzleStat = {
      id,
      started: results.length,
      solved: solved.length,
      avgAttempts: avg(solved.map((r) => r.attempts)),
      avgDurationSec: avg(durations),
      hintRate: solved.length ? solved.filter((r) => r.hintsBought.length > 0).length / solved.length : null,
      helpRate: solved.length ? solved.filter((r) => r.solvedBy === 'help').length / solved.length : null,
      flagged: false,
    };
    stat.flagged = (stat.avgDurationSec ?? 0) > FLAG_DURATION_SEC || (stat.helpRate ?? 0) > FLAG_HELP_RATE;
    return stat;
  });
}

export interface PuzzleTimeline {
  id: string;
  attempts: Array<{ input: string; correct: boolean; at: number }>;
  hints: string[];
  result: PuzzleResult | null;
}

export interface DayTimeline {
  day: number;
  startedAt: number | null;
  completedAt: number | null;
  durationSec: number | null;
  choices: Array<{ question: string; text: string }>;
  puzzles: PuzzleTimeline[];
  finds: Array<{ type: 'clue_found' | 'item_found' | 'spark_found'; id: string }>;
}

/** admin.player: one entry per day the player has touched, in day order. */
export function playerTimeline(save: SaveDoc | null, events: readonly AnyEvent[], catalog: readonly CatalogEntry[]): DayTimeline[] {
  const days = new Map<number, DayTimeline>();
  const dayOf = (day: number) => {
    if (!days.has(day)) {
      days.set(day, {
        day,
        startedAt: save?.progress.dayStartedAt[String(day)] ?? null,
        completedAt: save?.progress.dayCompletedAt[String(day)] ?? null,
        durationSec: null,
        choices: [],
        puzzles: [],
        finds: [],
      });
    }
    return days.get(day)!;
  };
  const puzzleOf = (t: DayTimeline, id: string) => {
    let p = t.puzzles.find((x) => x.id === id);
    if (!p) {
      p = { id, attempts: [], hints: [], result: save?.puzzles[id] ?? null };
      t.puzzles.push(p);
    }
    return p;
  };

  for (const day of [...Object.keys(save?.progress.dayStartedAt ?? {}), ...(save?.progress.completedDays ?? [])]) dayOf(Number(day));
  for (const e of events) {
    if (e.day === null) continue;
    const t = dayOf(e.day);
    const d = e.data;
    switch (e.type) {
      case 'day_start':
        t.startedAt ??= e.at;
        break;
      case 'day_complete':
        t.completedAt ??= e.at;
        if (typeof d.durationSec === 'number') t.durationSec = d.durationSec;
        break;
      case 'choice': {
        const entry = catalog.find((c) => c.id === d.cid);
        t.choices.push({
          question: entry?.question ?? String(d.cid),
          text: entry?.options.find((o) => o.option === d.option)?.text ?? String(d.label ?? d.option),
        });
        break;
      }
      case 'puzzle_start':
        puzzleOf(t, String(d.puzzleId));
        break;
      case 'puzzle_attempt':
        puzzleOf(t, String(d.puzzleId)).attempts.push({ input: String(d.input), correct: !!d.correct, at: e.at });
        break;
      case 'puzzle_hint':
        puzzleOf(t, String(d.puzzleId)).hints.push(d.level === 'super' ? 'Super' : `${String(d.level)}${d.free ? ' (frei)' : ''}`);
        break;
      case 'puzzle_solved':
        puzzleOf(t, String(d.puzzleId));
        break;
      case 'clue_found':
      case 'item_found':
      case 'spark_found':
        t.finds.push({ type: e.type, id: String(d.id) });
        break;
    }
  }
  for (const t of days.values()) {
    if (t.durationSec === null && t.startedAt && t.completedAt) t.durationSec = Math.round((t.completedAt - t.startedAt) / 1000);
  }
  return [...days.values()].sort((a, b) => a.day - b.day);
}
